-- Heart rate deviation episodes and the user's explanations, kept for later analysis; uid is generated by the phone.
-- direction: 0 high, 1 low. state: 0 sleep, 1 awake rest. Times are epoch ms; a set discarded_at means a workout explained it.
-- reasons is a JSON array of DeviationReason codes, empty without an answer: 1 heavy load, 2 hurrying, 3 stairs,
-- 10 unpleasant talk, 11 excitement, 20 coffee, 21 alcohol, 22 medication, 30 illness, 31 poor sleep, 32 feeling unwell,
-- 40 heat, 41 shower or sauna, 50 nothing special, 60 other.
CREATE TABLE deviation_episode (
    uid          TEXT             PRIMARY KEY,
    direction    SMALLINT         NOT NULL,
    state        SMALLINT         NOT NULL,
    started_at   BIGINT           NOT NULL,
    ended_at     BIGINT           NOT NULL,
    peak_bpm     DOUBLE PRECISION NOT NULL,
    reasons      JSONB            NOT NULL,
    detected_at  BIGINT           NOT NULL,
    asked_at     BIGINT,
    answered_at  BIGINT,
    discarded_at BIGINT,
    device_id    TEXT             NOT NULL,
    received_at  TIMESTAMPTZ      NOT NULL DEFAULT now()
);

CREATE INDEX deviation_episode_started_at ON deviation_episode (started_at);
